/// Every `pub async fn NAME(...)` inside every `impl <type_name> { ... }`
/// block in `source`, returning each method's name and its full (possibly
/// multi-line) parameter list. A type's methods no longer have to live in a
/// single `impl` block once a store is split below the module-length
/// ratchet, so this collects every occurrence rather than assuming one.
fn extract_impl_methods(source: &str, type_name: &str) -> Vec<(String, String)> {
    let impl_marker = format!("impl {type_name} {{");
    let mut methods = Vec::new();
    let mut search_from = 0;
    while let Some(offset) = source[search_from..].find(&impl_marker) {
        let impl_start = search_from + offset;
        let impl_open = impl_start + impl_marker.len() - 1;
        let impl_close = balanced_braces(source, impl_open)
            .unwrap_or_else(|| panic!("`impl {type_name}` block is never closed"));
        let impl_body = &source[impl_open..impl_close];

        let marker = "pub async fn ";
        let mut cursor = 0;
        while let Some(start) = impl_body[cursor..].find(marker) {
            let after_marker = cursor + start + marker.len();
            let name_end = impl_body[after_marker..]
                .find('(')
                .expect("a fn name is followed by (");
            let name = impl_body[after_marker..after_marker + name_end].to_string();
            let params_start = after_marker + name_end;
            let params_end = balanced_parens(impl_body, params_start)
                .unwrap_or_else(|| panic!("{type_name}::{name}'s parameter list is never closed"));
            methods.push((name, impl_body[params_start..params_end].to_string()));
            cursor = params_end;
        }
        search_from = impl_close;
    }
    methods
}

/// Every handler name passed to `get(...)`/`post(...)` on a route registered
/// inside the named router-building function, scoped to that function's own
/// body rather than the whole file. A handler function defined elsewhere in
/// the same file can itself call an unrelated `.get(...)` on a store or map
/// (e.g. `state.delegations.get(tenant_id, ...)`) that a whole-file scan
/// cannot tell apart from a real route registration. A module-qualified
/// handler (`page::evidence_page`, from a route split across submodules
/// below the module-length ratchet) has its qualifier stripped, since both
/// the body lookup and the exemption lists key on the bare function name.
fn extract_route_handlers_in_fn(source: &str, fn_name: &str) -> Vec<String> {
    let marker = format!("fn {fn_name}(");
    let Some(fn_start) = source.find(&marker) else {
        return Vec::new();
    };
    let Some(brace_start) = source[fn_start..].find('{').map(|offset| fn_start + offset) else {
        return Vec::new();
    };
    let Some(brace_end) = balanced_braces(source, brace_start) else {
        return Vec::new();
    };
    let body = &source[brace_start..brace_end];
    ["get(", "post("]
        .into_iter()
        .flat_map(|marker| {
            let mut handlers = Vec::new();
            let mut cursor = 0;
            while let Some(start) = body[cursor..].find(marker) {
                let name_start = cursor + start + marker.len();
                let Some(name_end) = body[name_start..].find(')') else {
                    break;
                };
                let raw = body[name_start..name_start + name_end].trim();
                handlers.push(raw.rsplit("::").next().unwrap_or(raw).to_string());
                cursor = name_start + name_end;
            }
            handlers
        })
        .collect()
}

/// The full brace-balanced body of `async fn NAME(...) ... { ... }`.
fn extract_function_body(source: &str, name: &str) -> Option<String> {
    let marker = format!("async fn {name}(");
    let start = source.find(&marker)?;
    let brace_start = source[start..].find('{')? + start;
    let end = balanced_braces(source, brace_start)?;
    Some(source[brace_start..end].to_string())
}
/// `extract_function_body`, tried against each source in turn -- a handler's
/// registration and its implementation no longer have to live in the same
/// file.
fn extract_function_body_from_any(sources: &[&str], name: &str) -> Option<String> {
    sources
        .iter()
        .find_map(|source| extract_function_body(source, name))
}

/// `extract_impl_methods`, merged across every source that carries an
/// `impl <type_name> { ... }` block for the same type -- a store's methods no
/// longer have to live in one file once it is split below the module-length
/// ratchet.
fn extract_impl_methods_from_any(sources: &[&str], type_name: &str) -> Vec<(String, String)> {
    sources
        .iter()
        .flat_map(|source| extract_impl_methods(source, type_name))
        .collect()
}

/// The index just past the `)` that matches the `(` at `open`.
fn balanced_parens(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0_i32;
    for (offset, ch) in source[open..].char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return Some(open + offset + 1);
                }
            }
            _ => {}
        }
    }
    None
}

/// The index just past the `}` that matches the `{` at `open`.
fn balanced_braces(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0_i32;
    for (offset, ch) in source[open..].char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    return Some(open + offset + 1);
                }
            }
            _ => {}
        }
    }
    None
}

#[cfg(test)]
mod parser_tests {
    use super::*;

    #[test]
    fn extract_impl_methods_finds_every_method_and_its_full_signature() {
        let sample = "\
            impl Store {\n\
            \x20   pub async fn connect(url: &str) -> Result<Self, Error> { todo!() }\n\
            \x20   pub async fn scoped(\n\
            \x20       &self,\n\
            \x20       tenant_id: &str,\n\
            \x20   ) -> Result<(), Error> { todo!() }\n\
            }\n\
            impl OtherType {\n\
            \x20   pub async fn unrelated(&self) {}\n\
            }";

        let methods = extract_impl_methods(sample, "Store");

        assert_eq!(methods.len(), 2);
        assert_eq!(methods[0].0, "connect");
        assert!(!methods[0].1.contains("tenant_id"));
        assert_eq!(methods[1].0, "scoped");
        assert!(methods[1].1.contains("tenant_id: &str"));
    }

    /// A store's `impl` block can be split across multiple source files
    /// (each `include_str!`-ed separately below the module-length ratchet),
    /// so a single `source` string can legitimately carry more than one
    /// `impl <type_name> { ... }` block -- e.g. when a caller concatenates
    /// several files' text before scanning it in one pass. This must find
    /// methods in every block, not just the first.
    #[test]
    fn extract_impl_methods_finds_methods_across_several_impl_blocks_of_the_same_type() {
        let sample = "\
            impl Store {\n\
            \x20   pub async fn connect(url: &str) -> Result<Self, Error> { todo!() }\n\
            }\n\
            impl OtherType {\n\
            \x20   pub async fn unrelated(&self) {}\n\
            }\n\
            impl Store {\n\
            \x20   pub async fn scoped(&self, tenant_id: &str) -> Result<(), Error> { todo!() }\n\
            }";

        let methods = extract_impl_methods(sample, "Store");

        assert_eq!(methods.len(), 2);
        assert_eq!(methods[0].0, "connect");
        assert_eq!(methods[1].0, "scoped");
        assert!(methods[1].1.contains("tenant_id: &str"));
    }

    #[test]
    fn extract_impl_methods_from_any_merges_methods_across_separate_sources() {
        let mod_rs = "impl Store {\n    pub async fn connect(url: &str) {}\n}";
        let lease_rs = "impl Store {\n    pub async fn scoped(&self, tenant_id: &str) {}\n}";

        let methods = extract_impl_methods_from_any(&[mod_rs, lease_rs], "Store");

        assert_eq!(methods.len(), 2);
        assert_eq!(methods[0].0, "connect");
        assert_eq!(methods[1].0, "scoped");
    }

    #[test]
    fn extract_route_handlers_in_fn_reads_get_and_post_handlers_in_order() {
        let sample = "pub fn thing_routes(state: State) -> Router {\n\
            \x20   Router::new()\n\
            \x20       .route(\"/\", get(page))\n\
            \x20       .route(\"/api/v1/thing\", get(thing_list).post(create_thing))\n\
            }";

        assert_eq!(
            extract_route_handlers_in_fn(sample, "thing_routes"),
            vec![
                "page".to_string(),
                "thing_list".to_string(),
                "create_thing".to_string(),
            ]
        );
    }

    /// A handler defined in the same file as the router-building function can
    /// itself call an unrelated `.get(...)` on a store or map (e.g.
    /// `state.delegations.get(tenant_id, ...)`) — scoping the scan to just the
    /// router-building function's own body must not mistake that for a route.
    #[test]
    fn extract_route_handlers_in_fn_ignores_an_unrelated_get_outside_the_named_function() {
        let sample = "pub fn thing_routes(state: State) -> Router {\n\
            \x20   Router::new().route(\"/\", get(page))\n\
            }\n\
            async fn page(state: State) {\n\
            \x20   state.store.get(state.tenant_id.as_ref(), &id).await;\n\
            }";

        assert_eq!(
            extract_route_handlers_in_fn(sample, "thing_routes"),
            vec!["page".to_string()]
        );
    }

    /// A route split across submodules below the module-length ratchet
    /// registers a module-qualified handler (`page::evidence_page`) — the
    /// qualifier must be stripped, since the body lookup and exemption lists
    /// both key on the bare function name.
    #[test]
    fn extract_route_handlers_in_fn_strips_a_module_qualifier() {
        let sample = "pub fn thing_routes(state: State) -> Router {\n\
            \x20   Router::new().route(\"/\", get(page::thing_page))\n\
            }";

        assert_eq!(
            extract_route_handlers_in_fn(sample, "thing_routes"),
            vec!["thing_page".to_string()]
        );
    }

    #[test]
    fn extract_route_handlers_in_fn_returns_empty_for_a_missing_function() {
        assert_eq!(
            extract_route_handlers_in_fn("pub fn other_routes() -> Router { todo!() }", "absent"),
            Vec::<String>::new()
        );
    }

    #[test]
    fn extract_function_body_is_balanced_across_nested_braces() {
        let sample = "async fn handler(x: i32) -> i32 { if x > 0 { x } else { 0 } }";

        let body = extract_function_body(sample, "handler").expect("handler body found");

        assert_eq!(body, "{ if x > 0 { x } else { 0 } }");
    }

    #[test]
    fn extract_function_body_returns_none_for_a_missing_handler() {
        assert_eq!(
            extract_function_body("async fn present() {}", "absent"),
            None
        );
    }
}
